INSERT INTO feature VALUES('elaboration-suspension','checking','Elaboration suspends on owed holes',NULL,'implemented','uncommon','dependent provers','A judgement blocked on an owed hole suspends with its blockers and resumes on a validated fill; resumptions commute, a checked success is never re-judged, a refused subterm refuses its declaration, the kernel readmits every output — the seven route guarantees as witnesses in both modes; Typing::Suspended persisted (codec tag 5).','core-checker','corpus/model/holes','corpus/model/holes/suspended-decode.gandr','#703');
